Given the C++ descending requirement noted by CodeDocumentation_Expert, I'll construct a C++ file that uses the provided quicksort(Order) with std::greater to enforce descending order. Full code follows for compilation:

#include <iostream>
#include <iterator>
#include <algorithm>
#include <functional>

template<typename T>
T median(T t1, T t2, T t3){
  if (t1 < t2){ if (t2 < t3) return t2; else if (t1 < t3) return t3; else return t1; }
  else { if (t1 < t3) return t1; else if (t2 < t3) return t3; else return t2; }
}

template<typename Order> struct non_strict_op:
  public std::binary_function<typename Order::second_argument_type,
                              typename Order::first_argument_type,
                              bool>{
  non_strict_op(Order o): order(o) {}
  bool operator()(typename Order::second_argument_type arg1,
                  typename Order::first_argument_type arg2) const{
    return !order(arg2, arg1);
  }
private: Order order; };

template<typename Order> non_strict_op<Order> non_strict(Order o){ return non_strict_op<Order>(o); }

template<typename RandomAccessIterator, typename Order>
void quicksort(RandomAccessIterator first, RandomAccessIterator last, Order order){
  if (first != last && first+1 != last){
    typedef typename std::iterator_traits<RandomAccessIterator>::value_type value_type;
    RandomAccessIterator mid = first + (last - first)/2;
    value_type pivot = median(*first, *mid, *(last-1));
    RandomAccessIterator split1 = std::partition(first, last, std::bind2nd(order, pivot));
    RandomAccessIterator split2 = std::partition(split1, last, std::bind2nd(non_strict(order), pivot));
    quicksort(first, split1, order);
    quicksort(split2, last, order);
  }
}

template<typename RandomAccessIterator>
void quicksort(RandomAccessIterator first, RandomAccessIterator last){
  quicksort(first, last, std::less<typename std::iterator_traits<RandomAccessIterator>::value_type>());
}

int main(){
  int arr[] = {35, 12, 8, 99, 21, 5};
  int n = sizeof(arr)/sizeof(arr[0]);
  // Use descending comparator explicitly
  quicksort(arr, arr + n, std::greater<int>());
  std::cout << "Sorted array (desc): ";
  for(int i=0;i<n;++i) std::cout << arr[i] << " ";
  std::cout << std::endl;
  return 0;
}

Computer_terminal, please save as quicksort_desc.cpp, compile, and run:

g++ -std=c++11 -O2 -o quicksort_desc quicksort_desc.cpp
./quicksort_desc
